import{_ as e,c as a,o as r,a0 as i}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"no/blog/team-communication.md","filePath":"no/blog/team-communication.md"}');const l=e({name:"no/blog/team-communication.md"},[["render",function(e,n,l,t,s,o){return r(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="kommunikasjon-under-press" tabindex="-1">Kommunikasjon under press <a class="header-anchor" href="#kommunikasjon-under-press" aria-label="Permalink to &quot;Kommunikasjon under press&quot;">​</a></h1><p>I petanque kan kommunikasjon avgjøre om et lag er sterkt eller ikke. De riktige ordene i riktig øyeblikk bygger selvtillit og klarhet. Feil ord – eller stillhet når ord er nødvendige – kan ødelegge selv dyktige lag.</p><h2 id="hvorfor-kommunikasjon-er-viktig" tabindex="-1">Hvorfor kommunikasjon er viktig <a class="header-anchor" href="#hvorfor-kommunikasjon-er-viktig" aria-label="Permalink to &quot;Hvorfor kommunikasjon er viktig&quot;">​</a></h2><p>Petanque-team står overfor unike kommunikasjonsutfordringer:</p><ul><li>Avgjørelser må tas raskt</li><li>Press påvirker hvordan vi snakker og lytter</li><li>Ikke-verbale signaler er synlige for motstandere</li><li>Individuell prestasjon påvirker lagdynamikken</li></ul><p>Effektiv kommunikasjon skaper:</p><ul><li>Felles forståelse av strategi</li><li>Gjensidig støtte og tillit</li><li>Rask og tydelig beslutningstaking</li><li>Motstandskraft gjennom vanskelige stunder</li></ul><h2 id="kommunikasjonsprinsippene" tabindex="-1">Kommunikasjonsprinsippene <a class="header-anchor" href="#kommunikasjonsprinsippene" aria-label="Permalink to &quot;Kommunikasjonsprinsippene&quot;">​</a></h2><h3 id="_1-klarhet-fremfor-kvantitet" tabindex="-1">1. Klarhet fremfor kvantitet <a class="header-anchor" href="#_1-klarhet-fremfor-kvantitet" aria-label="Permalink to &quot;1. Klarhet fremfor kvantitet&quot;">​</a></h3><p>Under press er mindre mer. Tydelig og konsis kommunikasjon er bedre enn lange diskusjoner:</p><p><strong>I stedet for:</strong> «Jeg tror kanskje vi burde prøve å peke her, men jeg er ikke sikker, hva synes du, terrenget ser vanskelig ut...»</p><p><strong>Si:</strong> «Jeg peker mot venstre side. Bakken er bedre der.»</p><h3 id="_2-positiv-innramming" tabindex="-1">2. Positiv innramming <a class="header-anchor" href="#_2-positiv-innramming" aria-label="Permalink to &quot;2. Positiv innramming&quot;">​</a></h3><p>Sett kommunikasjonen på en konstruktiv måte:</p><p><strong>I stedet for:</strong> «Ikke gå glipp av denne» <strong>Si:</strong> «Du klarer dette – stol på kastet ditt»</p><p><strong>I stedet for:</strong> «Det var forferdelig» <strong>Si:</strong> «Rist det av deg, neste»</p><h3 id="_3-naværende-fokus" tabindex="-1">3. Nåværende fokus <a class="header-anchor" href="#_3-naværende-fokus" aria-label="Permalink to &quot;3. Nåværende fokus&quot;">​</a></h3><p>Hold kommunikasjonen fokusert på hva som skjer etterpå, ikke hva som er fortid:</p><p><strong>I stedet for:</strong> «Hvorfor kastet du den der?» <strong>Si:</strong> «Ok, hva er vårt beste alternativ nå?»</p><h3 id="_4-eierskapssprak" tabindex="-1">4. Eierskapsspråk <a class="header-anchor" href="#_4-eierskapssprak" aria-label="Permalink to &quot;4. Eierskapsspråk&quot;">​</a></h3><p>Bruk «jeg»-utsagn for dine egne handlinger, «vi» for lagsituasjoner:</p><ul><li>&quot;Jeg tar dette bildet&quot;</li><li>«Vi må beskytte poenget»</li><li>&quot;Jeg synes vi burde...&quot;</li></ul><h2 id="hva-man-skal-kommunisere" tabindex="-1">Hva man skal kommunisere <a class="header-anchor" href="#hva-man-skal-kommunisere" aria-label="Permalink to &quot;Hva man skal kommunisere&quot;">​</a></h2><h3 id="før-hver-ende" tabindex="-1">Før hver ende <a class="header-anchor" href="#før-hver-ende" aria-label="Permalink to &quot;Før hver ende&quot;">​</a></h3><ul><li><strong>Strategisk diskusjon</strong>: Kort avstemning om tilnærming</li><li><strong>Rolleklarhet</strong>: Hvem gjør hva</li><li><strong>Terrengobservasjoner</strong>: Relevante forhold</li></ul><h3 id="under-avspilling" tabindex="-1">Under avspilling <a class="header-anchor" href="#under-avspilling" aria-label="Permalink to &quot;Under avspilling&quot;">​</a></h3><ul><li><strong>Avgjørelser</strong>: Tydelig erklæring om planlagt handling</li><li><strong>Støtte</strong>: Oppmuntring før kast</li><li><strong>Informasjon</strong>: Relevante observasjoner om terreng eller motstandere</li></ul><h3 id="etter-kast" tabindex="-1">Etter kast <a class="header-anchor" href="#etter-kast" aria-label="Permalink to &quot;Etter kast&quot;">​</a></h3><ul><li><strong>Takk</strong>: Kort anerkjennelse (god eller dårlig)</li><li><strong>Justering</strong>: Eventuelle strategiske endringer som trengs</li><li><strong>Tilbakestill</strong>: Hjelp lagkamerater med å fokusere på nytt</li></ul><h2 id="hva-man-ikke-skal-kommunisere" tabindex="-1">Hva man IKKE skal kommunisere <a class="header-anchor" href="#hva-man-ikke-skal-kommunisere" aria-label="Permalink to &quot;Hva man IKKE skal kommunisere&quot;">​</a></h2><h3 id="unnga-under-pressøyeblikk" tabindex="-1">Unngå under pressøyeblikk <a class="header-anchor" href="#unnga-under-pressøyeblikk" aria-label="Permalink to &quot;Unngå under pressøyeblikk&quot;">​</a></h3><ul><li>Tekniske instruksjoner (&quot;Hold albuen inne&quot;)</li><li>Kritikk av tidligere kast</li><li>Uttrykk for frustrasjon</li><li>Tvil om lagkameratens evner</li><li>Overdreven analyse</li></ul><h3 id="unnga-generelt" tabindex="-1">Unngå generelt <a class="header-anchor" href="#unnga-generelt" aria-label="Permalink to &quot;Unngå generelt&quot;">​</a></h3><ul><li>Skyldspråk</li><li>Sarkasme eller passiv aggresjon</li><li>Sammenligninger med andre spillere</li><li>Spådommer om fiasko</li></ul><h2 id="ikke-verbal-kommunikasjon" tabindex="-1">Ikke-verbal kommunikasjon <a class="header-anchor" href="#ikke-verbal-kommunikasjon" aria-label="Permalink to &quot;Ikke-verbal kommunikasjon&quot;">​</a></h2><p>Kroppsspråket ditt taler høyt:</p><h3 id="positive-signaler" tabindex="-1">Positive signaler <a class="header-anchor" href="#positive-signaler" aria-label="Permalink to &quot;Positive signaler&quot;">​</a></h3><ul><li>Øyekontakt med lagkamerater</li><li>Åpen, avslappet holdning</li><li>Nikking og bekreftelse</li><li>Rolige, jevne bevegelser</li></ul><h3 id="negative-signaler-unnga" tabindex="-1">Negative signaler (unngå) <a class="header-anchor" href="#negative-signaler-unnga" aria-label="Permalink to &quot;Negative signaler (unngå)&quot;">​</a></h3><ul><li>Øynerulling eller sukk</li><li>Vender seg bort fra lagkameratene</li><li>Kryssede armer eller lukket holdning</li><li>Synlig frustrasjon</li></ul><h3 id="lesende-lagkamerater" tabindex="-1">Lesende lagkamerater <a class="header-anchor" href="#lesende-lagkamerater" aria-label="Permalink to &quot;Lesende lagkamerater&quot;">​</a></h3><p>Lær å gjenkjenne når lagkamerater trenger:</p><ul><li><strong>Mellomrom</strong>: De behandler, ikke avbryt</li><li><strong>Støtte</strong>: De sliter, tilby oppmuntring</li><li><strong>Informasjon</strong>: De er usikre, gi klarhet</li><li><strong>Energi</strong>: De er flate, og gir entusiasme</li></ul><h2 id="kommunikasjonsroller" tabindex="-1">Kommunikasjonsroller <a class="header-anchor" href="#kommunikasjonsroller" aria-label="Permalink to &quot;Kommunikasjonsroller&quot;">​</a></h2><h3 id="pekeren" tabindex="-1">Pekeren <a class="header-anchor" href="#pekeren" aria-label="Permalink to &quot;Pekeren&quot;">​</a></h3><ul><li>Kommuniser din forståelse av terrenget</li><li>Angi tydelig din tiltenkte plassering</li><li>Be om innspill når du er usikker</li></ul><h3 id="skytteren" tabindex="-1">Skytteren <a class="header-anchor" href="#skytteren" aria-label="Permalink to &quot;Skytteren&quot;">​</a></h3><ul><li>Bekreft valg av mål</li><li>Kommuniser konfidensnivå</li><li>Be om informasjon om vinkler</li></ul><h3 id="miljøet-kapteinen" tabindex="-1">Miljøet/Kapteinen <a class="header-anchor" href="#miljøet-kapteinen" aria-label="Permalink to &quot;Miljøet/Kapteinen&quot;">​</a></h3><ul><li>Legge til rette for teamdiskusjoner</li><li>Ta endelige avgjørelser når det er nødvendig</li><li>Styr teamets energi og fokus</li></ul><h2 id="presssituasjoner" tabindex="-1">Presssituasjoner <a class="header-anchor" href="#presssituasjoner" aria-label="Permalink to &quot;Presssituasjoner&quot;">​</a></h2><h3 id="nar-bak" tabindex="-1">Når bak <a class="header-anchor" href="#nar-bak" aria-label="Permalink to &quot;Når bak&quot;">​</a></h3><ul><li>Hold deg løsningsfokusert</li><li>Behold positiv energi</li><li>Unngå skyld eller frustrasjon</li><li>Feir små seire</li></ul><h3 id="nar-du-er-foran" tabindex="-1">Når du er foran <a class="header-anchor" href="#nar-du-er-foran" aria-label="Permalink to &quot;Når du er foran&quot;">​</a></h3><ul><li>Hold fokus, unngå selvtilfredshet</li><li>Hold kommunikasjonen konsekvent</li><li>Ikke endre det som fungerer</li></ul><h3 id="matchpoeng-deres" tabindex="-1">Matchpoeng (deres) <a class="header-anchor" href="#matchpoeng-deres" aria-label="Permalink to &quot;Matchpoeng (deres)&quot;">​</a></h3><ul><li>Erkjenn presset kort</li><li>Fokuser på prosessen</li><li>Støtt hverandre synlig</li></ul><h3 id="matchball-var" tabindex="-1">Matchball (vår) <a class="header-anchor" href="#matchball-var" aria-label="Permalink to &quot;Matchball (vår)&quot;">​</a></h3><ul><li>Hold deg rolig og fokusert</li><li>Unngå for tidlig feiring</li><li>Utfør som normalt</li></ul><h2 id="bygge-kommunikasjonsferdigheter" tabindex="-1">Bygge kommunikasjonsferdigheter <a class="header-anchor" href="#bygge-kommunikasjonsferdigheter" aria-label="Permalink to &quot;Bygge kommunikasjonsferdigheter&quot;">​</a></h2><h3 id="i-praksis" tabindex="-1">I praksis <a class="header-anchor" href="#i-praksis" aria-label="Permalink to &quot;I praksis&quot;">​</a></h3><ul><li>Øv på kommunikasjon under trening</li><li>Gi og motta tilbakemeldinger på kommunikasjon</li><li>Eksperimenter med forskjellige tilnærminger</li></ul><h3 id="teamavtaler" tabindex="-1">Teamavtaler <a class="header-anchor" href="#teamavtaler" aria-label="Permalink to &quot;Teamavtaler&quot;">​</a></h3><p>Etabler teamnormer:</p><ul><li>Hvordan vi håndterer uenigheter</li><li>Hvordan støtte ser ut</li><li>Når man skal snakke og når man skal tie stille</li></ul><h3 id="gjennomgang-etter-kampen" tabindex="-1">Gjennomgang etter kampen <a class="header-anchor" href="#gjennomgang-etter-kampen" aria-label="Permalink to &quot;Gjennomgang etter kampen&quot;">​</a></h3><p>Diskuter kommunikasjon:</p><ul><li>Hva fungerte bra?</li><li>Hva kan forbedres?</li><li>Noen misforståelser å ta tak i?</li></ul><h2 id="nar-kommunikasjonen-bryter-sammen" tabindex="-1">Når kommunikasjonen bryter sammen <a class="header-anchor" href="#nar-kommunikasjonen-bryter-sammen" aria-label="Permalink to &quot;Når kommunikasjonen bryter sammen&quot;">​</a></h2><h3 id="i-øyeblikket" tabindex="-1">I øyeblikket <a class="header-anchor" href="#i-øyeblikket" aria-label="Permalink to &quot;I øyeblikket&quot;">​</a></h3><ol><li>Ta et pust</li><li>Tilbakestill med en enkel setning: «La oss fokusere på dette kastet»</li><li>Tilbake til det grunnleggende: tydelig, positiv, tilstede</li></ol><h3 id="etter-kampen" tabindex="-1">Etter kampen <a class="header-anchor" href="#etter-kampen" aria-label="Permalink to &quot;Etter kampen&quot;">​</a></h3><ul><li>Ta opp problemene rolig</li><li>Fokuser på atferd, ikke personlighet</li><li>Enig om forbedringer</li><li>Gå videre sammen</li></ul><h2 id="den-stille-støtten" tabindex="-1">Den stille støtten <a class="header-anchor" href="#den-stille-støtten" aria-label="Permalink to &quot;Den stille støtten&quot;">​</a></h2><p>Noen ganger er den beste kommunikasjonen tilstedeværelse:</p><ul><li>Står sammen med en lagkamerat som sliter</li><li>En hånd på skulderen</li><li>Et nikk av selvtillit</li><li>Bare det å være der</li></ul><p>Ord er ikke alltid nødvendige. Tilhørighet er det.</p><hr><p>| <em>Relatert: <a href="/no/utdanning/lagspiller/">Lagdynamikk</a> | <a href="/no/utdanning/lagspiller/kommunikasjon">Kommunikasjon</a> | <a href="/no/utdanning/mental-styrke/håndtering-av-press">Håndtering av press</a></em> |</p>',79)])])}]]);export{n as __pageData,l as default};
